package com.musteritakipcrm.alarm;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.content.res.ColorStateList;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.text.InputFilter;import android.text.InputType;import android.view.*;import android.widget.*;import java.security.MessageDigest;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity{
 private static final String PREF="crm_alarm",M2="\u2063\u200B",M3="\u2063\u200C"; private LinearLayout body,list; private int page=1; private boolean archive=false,n3Unlocked=false; private String calendarDay=""; private List<Api.Entry> cache=new ArrayList<>(); private final Set<Integer> open=new HashSet<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);AlarmRingingService.ensureChannels(this);requestPermissionsIfNeeded();setContentView(ui());if(token().isEmpty())pairDialog();else{startServiceNow();load();}}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
 private LinearLayout ui(){LinearLayout root=v();root.setBackgroundColor(Color.rgb(242,246,250));TextView h=t("📝 AJANDAM",21,true);h.setGravity(Gravity.CENTER);h.setPadding(dp(18),dp(15),dp(18),dp(15));h.setBackgroundColor(Color.rgb(255,202,40));root.addView(h,new LinearLayout.LayoutParams(-1,-2));body=v();body.setPadding(dp(8),dp(6),dp(8),dp(8));root.addView(body,new LinearLayout.LayoutParams(-1,-1));buildPage();return root;}
 private void buildPage(){body.removeAllViews();LinearLayout nav=new LinearLayout(this);String[] names={"NOT 1","NOT 2","🔒 NOT 3","📅 TAKVİM"};for(int i=0;i<4;i++){final int p=i+1;Button b=new Button(this);b.setText(names[i]);b.setTextSize(10);b.setOnClickListener(x->openPage(p));nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}body.addView(nav);LinearLayout tools=new LinearLayout(this);Button add=new Button(this);add.setText("+ YENİ NOT");add.setTextSize(13);add.setTypeface(null,Typeface.BOLD);add.setOnClickListener(x->{if(connected())editForm(null,page==4?1:page,calendarDay);});Button arc=new Button(this);arc.setText(archive?"✓ ARŞİV":"ARŞİV");arc.setTextSize(12);arc.setOnClickListener(x->{archive=!archive;buildPage();if(page==4)renderCalendar();else render(cache);});tools.addView(add,new LinearLayout.LayoutParams(0,-2,1));tools.addView(arc,new LinearLayout.LayoutParams(0,-2,1));body.addView(tools);if(page==4){renderCalendar();return;}ScrollView sc=new ScrollView(this);list=v();sc.addView(list);body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));if(token().isEmpty())pairDialog();else render(cache);}
 private void openPage(int p){if(p==3&&!n3Unlocked){pinDialog();return;}if(page==3&&p!=3)n3Unlocked=false;page=p;archive=false;buildPage();if(p!=4)load();else if(cache.isEmpty())load();}
 private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());} private boolean visibleMain(Api.Entry e){return !e.archived()||e.date.compareTo(today())>=0;} private boolean visibleArchive(Api.Entry e){return e.archived()&&e.date.compareTo(today())<0;}
 private void render(List<Api.Entry> all){if(list==null)return;list.removeAllViews();int n=0;for(Api.Entry e:all){if(cat(e)!=page)continue;if(archive?!visibleArchive(e):!visibleMain(e))continue;n++;list.addView(entryRow(e),rowParams());}if(n==0)list.addView(t(archive?"Arşiv boş.":"Henüz kayıt yok.",13,false));}
 private View entryRow(Api.Entry e){LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.HORIZONTAL);outer.setGravity(Gravity.CENTER_VERTICAL);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.rgb(252,253,249));bg.setCornerRadius(dp(14));bg.setStroke(dp(1),Color.rgb(125,174,199));outer.setBackground(bg);outer.setPadding(dp(6),dp(6),dp(5),dp(6));CheckBox done=new CheckBox(this);done.setChecked(e.archived());if(Build.VERSION.SDK_INT>=21)done.setButtonTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{Color.rgb(62,185,145),Color.rgb(145,160,170)}));done.setOnClickListener(x->archive(e,done.isChecked()));outer.addView(done,new LinearLayout.LayoutParams(-2,-2));LinearLayout middle=v();middle.setPadding(dp(4),0,dp(5),0);TextView title=t(titleOf(e.note),16,true);title.setSingleLine(true);title.setEllipsize(android.text.TextUtils.TruncateAt.END);middle.addView(title,new LinearLayout.LayoutParams(-1,-2));View line=new View(this);line.setBackgroundColor(Color.rgb(155,174,184));LinearLayout.LayoutParams lpLine=new LinearLayout.LayoutParams(-1,dp(1));lpLine.setMargins(0,dp(2),0,dp(4));middle.addView(line,lpLine);if(!e.remindAt.isEmpty()){TextView chip=t("🔔 "+dayMonthSlash(e.date)+" "+timeOnly(e.remindAt),11,true);chip.setGravity(Gravity.CENTER);GradientDrawable cbg=new GradientDrawable();cbg.setColor(Color.rgb(255,244,190));cbg.setCornerRadius(dp(9));chip.setBackground(cbg);chip.setPadding(dp(8),dp(3),dp(8),dp(3));middle.addView(chip,new LinearLayout.LayoutParams(-2,-2));}if(open.contains(e.id)){String d=detailOf(e.note);if(!d.isEmpty()){TextView desc=t(d,12,false);desc.setPadding(0,dp(6),0,dp(3));middle.addView(desc);}}middle.setOnClickListener(x->{if(open.contains(e.id))open.remove(e.id);else open.add(e.id);render(cache);});outer.addView(middle,new LinearLayout.LayoutParams(0,-2,1));TextView menu=t("⋮",26,true);menu.setGravity(Gravity.CENTER);GradientDrawable mbg=new GradientDrawable();mbg.setColor(Color.rgb(224,240,248));mbg.setCornerRadius(dp(10));menu.setBackground(mbg);menu.setOnClickListener(v->showEntryMenu(e,menu));outer.addView(menu,new LinearLayout.LayoutParams(dp(46),dp(52)));return outer;}
 private void showEntryMenu(Api.Entry e,View anchor){PopupMenu p=new PopupMenu(this,anchor);p.getMenu().add("Düzenle");p.getMenu().add("Panoya Ekle");p.getMenu().add(e.archived()?"Arşivden Çıkar":"Arşive Al");p.getMenu().add("Sil");p.setOnMenuItemClickListener(m->{String s=m.getTitle().toString();if(s.equals("Düzenle"))editForm(e,cat(e),"");else if(s.equals("Panoya Ekle"))copyToClipboard(titleOf(e.note),detailOf(e.note));else if(s.equals("Sil"))delete(e);else archive(e,!e.archived());return true;});p.show();}
 private void copyToClipboard(String bas,String det){String text=bas+(det.isEmpty()?"":"\n"+det);ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(ClipData.newPlainText("AJANDAM",text));show("Panoya eklendi.");}
 private void pasteFromClipboard(EditText title,EditText detail){ClipboardManager cm=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(!cm.hasPrimaryClip()||cm.getPrimaryClip()==null||cm.getPrimaryClip().getItemCount()==0){show("Panoda metin yok.");return;}CharSequence cs=cm.getPrimaryClip().getItemAt(0).coerceToText(this);String text=cs==null?"":cs.toString().trim();if(text.isEmpty()){show("Panoda metin yok.");return;}if(title.getText().toString().trim().isEmpty()){int p=text.indexOf('\n');title.setText(p<0?text:text.substring(0,p).trim());if(p>=0)detail.setText(text.substring(p+1).trim());}else{int start=Math.max(0,detail.getSelectionStart());detail.getText().insert(start,text);} }
 private String dayMonth(String d){try{return new SimpleDateFormat("dd.MM",Locale.US).format(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(d));}catch(Exception x){return d;}} private String dayMonthSlash(String d){try{return new SimpleDateFormat("dd/MM",Locale.US).format(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(d));}catch(Exception x){return d;}} private String timeOnly(String r){int p=r.indexOf(' ');return p>=0?r.substring(p+1):r;} private LinearLayout.LayoutParams rowParams(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));return p;}
 private void editForm(Api.Entry e,int category,String forcedDay){LinearLayout form=v();form.setPadding(dp(22),dp(3),dp(22),0);EditText title=new EditText(this);title.setHint("Başlık");title.setTextSize(17);title.setTypeface(null,Typeface.BOLD);title.setSingleLine(true);title.setText(e==null?"":titleOf(e.note));form.addView(title);EditText detail=new EditText(this);detail.setHint("Açıklama");detail.setTextSize(12);detail.setMinLines(2);detail.setText(e==null?"":detailOf(e.note));form.addView(detail);LinearLayout clip=new LinearLayout(this);Button paste=new Button(this);paste.setText("YAPIŞTIR");paste.setTextSize(11);paste.setOnClickListener(v->pasteFromClipboard(title,detail));Button copy=new Button(this);copy.setText("PANOYA EKLE");copy.setTextSize(11);copy.setOnClickListener(v->copyToClipboard(title.getText().toString().trim(),detail.getText().toString().trim()));clip.addView(paste,new LinearLayout.LayoutParams(0,-2,1));clip.addView(copy,new LinearLayout.LayoutParams(0,-2,1));form.addView(clip);Calendar c=Calendar.getInstance();String initial=e!=null?e.date:forcedDay;if(initial!=null&&!initial.isEmpty())try{c.setTime(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(initial));}catch(Exception ignored){}final String[] day={fmt(c,"yyyy-MM-dd")};Button date=new Button(this);date.setText("📅 "+dayMonth(day[0]));date.setTextSize(12);date.setOnClickListener(v->new DatePickerDialog(this,(z,y,m,dd)->{c.set(y,m,dd);day[0]=fmt(c,"yyyy-MM-dd");date.setText("📅 "+dayMonth(day[0]));},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show());form.addView(date,new LinearLayout.LayoutParams(-1,-2));LinearLayout tm=new LinearLayout(this);tm.setOrientation(LinearLayout.HORIZONTAL);tm.setGravity(Gravity.CENTER);tm.setPadding(0,dp(5),0,dp(4));TextView bell=t("⏰",20,false);bell.setGravity(Gravity.CENTER);tm.addView(bell,new LinearLayout.LayoutParams(dp(42),dp(54)));EditText hour=timeBox();EditText minute=timeBox();if(e!=null&&!e.remindAt.isEmpty()){String[] p=timeOnly(e.remindAt).split(":");if(p.length==2){hour.setText(p[0]);minute.setText(p[1]);}}tm.addView(hour,new LinearLayout.LayoutParams(dp(78),dp(54)));TextView colon=t(":",21,true);colon.setGravity(Gravity.CENTER);tm.addView(colon,new LinearLayout.LayoutParams(dp(24),dp(54)));tm.addView(minute,new LinearLayout.LayoutParams(dp(78),dp(54)));form.addView(tm);AlertDialog dlg=new AlertDialog.Builder(this).setTitle(e==null?"Yeni Not":"Düzenle").setView(form).setNegativeButton("VAZGEÇ",null).setPositiveButton("KAYDET",null).create();dlg.setOnShowListener(x->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String bas=title.getText().toString().trim(),det=detail.getText().toString().trim(),hs=hour.getText().toString().trim(),ms=minute.getText().toString().trim();if(bas.isEmpty()){show("Başlık boş olamaz.");return;}String rem="";if(!hs.isEmpty()||!ms.isEmpty()){if(hs.isEmpty()||ms.isEmpty()){show("Saat ve dakikayı birlikte yazın.");return;}try{int h=Integer.parseInt(hs),m=Integer.parseInt(ms);if(h<0||h>23||m<0||m>59){show("Geçerli bir saat girin.");return;}rem=day[0]+" "+String.format(Locale.US,"%02d:%02d",h,m);}catch(Exception q){show("Geçerli bir saat girin.");return;}}String note=pack(category,bas+(det.isEmpty()?"":"\n"+det));dlg.dismiss();if(e==null)save(day[0],note,rem);else update(e.id,day[0],note,rem);}));dlg.show();}
 private EditText timeBox(){EditText x=new EditText(this);x.setTextSize(19);x.setSingleLine(true);x.setGravity(Gravity.CENTER);x.setInputType(InputType.TYPE_CLASS_NUMBER);x.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2)});GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(8));g.setStroke(dp(1),Color.rgb(130,150,165));x.setBackground(g);x.setPadding(dp(5),0,dp(5),0);return x;}
 private void renderCalendar(){if(body.getChildCount()>2)body.removeViews(2,body.getChildCount()-2);CalendarView cv=new CalendarView(this);cv.setFirstDayOfWeek(Calendar.MONDAY);body.addView(cv,new LinearLayout.LayoutParams(-1,-2));TextView dayTitle=t("",14,true);body.addView(dayTitle);ScrollView sc=new ScrollView(this);list=v();sc.addView(list);body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Calendar c=Calendar.getInstance();if(calendarDay.isEmpty())calendarDay=fmt(c,"yyyy-MM-dd");showCalendarDay(dayTitle);cv.setOnDateChangeListener((view,y,m,d)->{calendarDay=String.format(Locale.US,"%04d-%02d-%02d",y,m+1,d);showCalendarDay(dayTitle);});}
 private void showCalendarDay(TextView title){title.setText("📅 "+dayMonth(calendarDay));list.removeAllViews();int n=0;for(Api.Entry e:cache){if(!e.date.equals(calendarDay))continue;if(cat(e)==3&&!n3Unlocked)continue;if(archive?!visibleArchive(e):!visibleMain(e))continue;n++;list.addView(entryRow(e),rowParams());}if(n==0)list.addView(t("Bu gün için kayıt yok.",12,false));}
 private int cat(Api.Entry e){return e.note.startsWith(M2)?2:e.note.startsWith(M3)?3:1;} private String clean(String n){return n.startsWith(M2)||n.startsWith(M3)?n.substring(2):n;} private String pack(int c,String n){return c==2?M2+n:c==3?M3+n:n;} private String titleOf(String n){n=clean(n);int p=n.indexOf('\n');return(p<0?n:n.substring(0,p)).trim();} private String detailOf(String n){n=clean(n);int p=n.indexOf('\n');return p<0?"":n.substring(p+1).trim();}
 private void load(){if(token().isEmpty()){pairDialog();return;}new Thread(()->{try{List<Api.Entry>a=Api.agenda(token());runOnUiThread(()->{cache=a;if(page==4)buildPage();else render(a);});}catch(Exception e){runOnUiThread(()->show("Ajanda alınamadı: "+e.getMessage()));}}).start();} private void save(String d,String n,String r){new Thread(()->{try{Api.addEntry(token(),d,n,r);runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->show("Kaydedilemedi: "+e.getMessage()));}}).start();} private void update(int id,String d,String n,String r){new Thread(()->{try{Api.updateEntry(token(),id,d,n,r);runOnUiThread(this::load);}catch(Exception e){runOnUiThread(()->show("Güncellenemedi: "+e.getMessage()));}}).start();} private void archive(Api.Entry e,boolean a){new Thread(()->{try{Api.archive(token(),e.id,a);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->show(x.getMessage()));}}).start();}
 private void delete(Api.Entry e){new AlertDialog.Builder(this).setTitle("Notu Sil").setMessage("Bu not silinsin mi?").setNegativeButton("HAYIR",null).setPositiveButton("SİL",(d,w)->new Thread(()->{try{Api.deleteEntry(token(),e.id);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->show(x.getMessage()));}}).start()).show();}
 private void pinDialog(){String saved=getSharedPreferences(PREF,MODE_PRIVATE).getString("n3_pin","");EditText pin=new EditText(this);pin.setHint(saved.isEmpty()?"4 haneli PIN belirleyin":"PIN'inizi girin");pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);AlertDialog d=new AlertDialog.Builder(this).setTitle("NOT 3 - Özel").setView(pin).setNegativeButton("VAZGEÇ",null).setPositiveButton(saved.isEmpty()?"PIN OLUŞTUR":"AÇ",null).create();d.setOnShowListener(z->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{String s=pin.getText().toString().trim();if(s.length()!=4){show("4 haneli PIN girin.");return;}String h=hash(s);if(saved.isEmpty())getSharedPreferences(PREF,MODE_PRIVATE).edit().putString("n3_pin",h).apply();else if(!saved.equals(h)){show("PIN yanlış.");return;}n3Unlocked=true;page=3;d.dismiss();buildPage();load();}));d.show();}
 private String hash(String s){try{byte[]b=MessageDigest.getInstance("SHA-256").digest(s.getBytes("UTF-8"));StringBuilder x=new StringBuilder();for(byte q:b)x.append(String.format(Locale.US,"%02x",q));return x.toString();}catch(Exception e){return s;}}
 private boolean connected(){if(!token().isEmpty())return true;pairDialog();return false;} private void pairDialog(){if(list==null)return;list.removeAllViews();list.addView(t("Site ajandanızla bağlantı yapın.",14,true));Button b=new Button(this);b.setText("SİTEYE BAĞLAN");b.setOnClickListener(v->showCodeDialog());list.addView(b);} private void showCodeDialog(){EditText code=new EditText(this);code.setHint("6 haneli kod");code.setInputType(InputType.TYPE_CLASS_NUMBER);AlertDialog d=new AlertDialog.Builder(this).setTitle("AJANDAM'ı Bağla").setView(code).setNegativeButton("VAZGEÇ",null).setPositiveButton("BAĞLA",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String c=code.getText().toString().trim();if(c.length()!=6){show("6 haneli kodu girin.");return;}new Thread(()->{try{String tok=Api.pair(c,"AJANDAM");getSharedPreferences(PREF,MODE_PRIVATE).edit().putString("token",tok).apply();runOnUiThread(()->{d.dismiss();startServiceNow();load();});}catch(Exception e){runOnUiThread(()->show("Bağlantı olmadı: "+e.getMessage()));}}).start();}));d.show();}
 private void show(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();} private String token(){return getSharedPreferences(PREF,MODE_PRIVATE).getString("token","");} private LinearLayout v(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);return x;} private TextView t(String s,int z,boolean b){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(Color.BLACK);if(b)x.setTypeface(null,Typeface.BOLD);x.setPadding(dp(5),dp(3),dp(5),dp(3));return x;} private String fmt(Calendar c,String p){return new SimpleDateFormat(p,Locale.US).format(c.getTime());} private void startServiceNow(){Intent i=new Intent(this,SyncService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);} private void requestPermissionsIfNeeded(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},20);}
}